//! SSE chunk → [`ModelEvent`] translation.
//!
//! Two invariants carry this module:
//!
//! 1. **`Finish` is emitted only from [`ChatTranslator::finish`]**, called at
//!    `[DONE]`/EOF — never inline with a chunk. With
//!    `stream_options.include_usage`, the usage snapshot arrives in a chunk
//!    *after* the one carrying `finish_reason`, so an inline `Finish` would be
//!    followed by `Usage` and violate core's "Finish is the terminal event"
//!    contract on every turn.
//! 2. **Tool-call `name`/`arguments` are buffered until the `id` is known,
//!    and `name` keeps buffering past that point**, because the id is not
//!    guaranteed to arrive first, and both fields fragment across deltas.
//!    Once the id is known, `arguments` drains on every delta, but `name`
//!    keeps accumulating until a completion signal (a delta carrying
//!    arguments, or one carrying no name fragment) or the end-of-stream
//!    flush releases it. A delta that carries neither `index` nor `id`
//!    is correlated by its position within `delta.tool_calls`, but only
//!    when *no* entry in that same array carries an explicit `index` — a
//!    synthesized positional key must never be allowed to collide with a
//!    genuine explicit index elsewhere in the array, which would silently
//!    merge two distinct calls. A mixed array (some entries indexed, one
//!    not) is non-conforming for OpenAI-compatible streaming; the
//!    ambiguous entry is skipped with a loud warning rather than guessed.
//!    Correlation itself is canonicalized: once a delta resolves the call's
//!    `id`, the key becomes `Key::Id(call_id)` and any fragments buffered
//!    under the pre-canonical key migrate into that slot in buffer-creation
//!    order. One `call_id` therefore owns exactly one state entry, which is
//!    what makes "at most one name-carrying delta per non-blank `call_id`"
//!    structural rather than guarded (SMA-550). The qualifier is load-bearing:
//!    a blank `id` is not an identity, so it is filtered out of the wire key
//!    and exempted from the end-of-stream dedup net, and two parallel
//!    blank-id calls therefore emit two names under `""` (SMA-616).

use std::collections::{HashMap, HashSet};

use paigasus_helikon_core::{FinishReason, ModelEvent};

use crate::sse::{StreamChunk, ToolCallChunk};

/// Correlation key for a streaming tool call.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum Key {
    /// Correlated by `delta.tool_calls[].index`, when present — or, as a
    /// last resort, by position within `delta.tool_calls` (in OpenAI-
    /// compatible streaming the array position *is* the index, so a
    /// positional continuation delta correctly joins a call already keyed
    /// by `Index`). Once a call's `id` resolves, `Index` is only ever a wire
    /// key again — its state has migrated to the canonical [`Key::Id`]. See
    /// [`ChatTranslator::canonicalize`].
    Index(u32),
    /// Correlated by `delta.tool_calls[].id`.
    ///
    /// Reached two ways: as the wire key when `index` is absent, and — since
    /// SMA-550 — as the *canonical* key for every call whose `id` has
    /// resolved, whether or not it also carried an `index`. See
    /// [`ChatTranslator::canonicalize`].
    Id(String),
}

/// Buffered name and args fragments for a tool call.
///
/// Both fields start out buffered here regardless of whether the call's
/// `id` is known yet. Once the id is known, `args` is drain-once — taken on
/// the first delta after the id is observed and never re-prepended — while
/// `name` keeps accumulating across every delta and is cleared only when it
/// flushes (SMA-547 §1).
///
/// **No `Default` impl, deliberately.** Every buffer must carry the `seq` it
/// was created with, so construction goes through [`Pending::new`] via
/// [`ChatTranslator::ensure_pending`]. Deriving `Default` would let an
/// `.or_default()` call site silently mint a buffer with `seq: 0`, which
/// would corrupt the merge order in [`ChatTranslator::canonicalize`]
/// (SMA-550). The absence of the derive is what makes that a compile error
/// rather than a latent bug.
struct Pending {
    /// Monotonic creation order across all buffers in one stream.
    ///
    /// Used to merge two buffers for one call in wire order (SMA-550) and to
    /// give `flush_buffered_names` a deterministic end-of-stream order.
    seq: u64,
    /// Accumulated function-name fragments.
    name: String,
    /// Accumulated JSON-arguments fragments.
    args: String,
}

impl Pending {
    /// An empty buffer stamped with its creation order.
    fn new(seq: u64) -> Self {
        Self {
            seq,
            name: String::new(),
            args: String::new(),
        }
    }
}

/// Accumulates SSE deltas and produces [`ModelEvent`]s.
///
/// One instance tracks a single streamed response. `consume` is called once
/// per chunk in order; `finish` is called once at stream end (`[DONE]` or
/// EOF) to emit the terminal event, if any.
pub(crate) struct ChatTranslator {
    /// Resolved call ids, keyed by correlation [`Key`].
    ///
    /// Holds both wire keys (`Key::Index(i)`, so later index-only deltas keep
    /// resolving) and the canonical `Key::Id(call_id) -> call_id` self-mapping
    /// that [`Self::canonicalize`] registers. The self-mapping is load-bearing:
    /// `flush_buffered_names` and `warn_unresolved_pending` both resolve a
    /// pending key through this map.
    tool_calls: HashMap<Key, String>,
    /// Canonical key → the tool name already emitted to the consumer.
    ///
    /// Holds the *value*, not just the key, so a late fragment can be told
    /// apart from a backend that repeats the whole name on every delta
    /// (SMA-547 §3).
    name_emitted: HashMap<Key, String>,
    /// Keys for which the late-name-fragment warning has already fired, so a
    /// chatty backend cannot produce one warn per argument chunk.
    warned_late_name: HashSet<Key>,
    /// Name/args fragments buffered per call.
    ///
    /// Keyed by the canonical key once the call's `id` resolves, so one
    /// `call_id` never owns two buffers (SMA-550).
    ///
    /// `args` is drain-once: taken on the first delta after the call's `id`
    /// is known and never re-prepended. `name` accumulates across every delta
    /// and is cleared only when the name flushes (SMA-547 §1).
    pending: HashMap<Key, Pending>,

content.content:
180	    ///
181	    /// Deliberately returns nothing rather than `&mut Pending`: callers then
182	    /// reach the buffer through `self.pending.get_mut(..)`, which borrows one
183	    /// field instead of all of `self` and so leaves the surrounding
184	    /// disjoint-field borrows of `name_emitted` and `tool_calls` intact.
185	    fn ensure_pending(&mut self, key: &Key) {
186	        if !self.pending.contains_key(key) {
187	            self.pending
188	                .insert(key.clone(), Pending::new(self.next_seq));
189	            self.next_seq += 1;
190	        }
191	    }
192	
193	    /// Rewrite `key` to the canonical slot for `call_id`, migrating any
194	    /// fragments buffered under the pre-canonical key.
195	    ///
196	    /// Every delta for one call — however it was keyed on the wire — shares a
197	    /// single state entry from here on. That is what makes "at most one
198	    /// name-carrying `ToolCallDelta` per non-blank `call_id`" hold by
199	    /// construction rather than by guard, and it is what lets a name
200	    /// fragmented across the `Key::Index` / `Key::Id` boundary reassemble
201	    /// instead of losing a fragment (SMA-550). Blank ids are excluded: this
202	    /// function returns them unchanged rather than canonicalizing them, so
203	    /// they carry no per-`call_id` invariant at all (SMA-616).
204	    fn canonicalize(&mut self, key: Key, call_id: &str) -> Key {
205	        // An empty `id` is not an identity. A backend that sends `"id": ""` on
206	        // every entry would otherwise collapse every one of its parallel calls
207	        // into a single `Key::Id("")` slot, and all but the first would vanish
208	        // from the stream entirely — a strictly worse outcome than the
209	        // dual-keying this function exists to fix. Leave such deltas on their
210	        // wire key. That keeps distinct calls distinct only because a blank id
211	        // is filtered out when the wire key is chosen (see `handle_tool_call`)
212	        // — otherwise two blank-id entries with no `index` would both arrive
213	        // here already sharing one `Key::Id("")` slot (SMA-616).
214	        if call_id.is_empty() {
215	            if self.warned_blank_id.insert(key.clone()) {
216	                tracing::warn!(
217	                    target: "paigasus::litellm::stream",
218	                    ?key,
219	                    "tool-call delta carries an empty id; correlating by wire key \
220	                     instead, since an empty id cannot identify a call"
221	                );
222	            }
223	            return key;
224	        }
225	        // Already canonical — return without allocating. Reached only when the
226	        // delta was keyed by `id` with no `index`; LiteLLM itself sends `index`
227	        // on every delta, so its streams fall through and clone the `call_id`
228	        // once per delta. That clone is accepted — every emitted
229	        // `ToolCallDelta` already pays one.
230	        if matches!(&key, Key::Id(id) if id == call_id) {
231	            return key;
232	        }
233	        let canonical = Key::Id(call_id.to_owned());
234	
235	        if let Some(old) = self.pending.remove(&key) {
236	            self.ensure_pending(&canonical);
237	            let slot = self
238	                .pending
239	                .get_mut(&canonical)
240	                .expect("ensure_pending just inserted this key");
241	
242	            // A resolved slot drains `args` on every delta and is removed once
243	            // both fields are empty, so `slot.args` is always empty here --
244	            // which is what makes `insert_str(0, ..)` below an assignment in
245	            // practice rather than a splice. The assert does not guard
246	            // correctness: `insert_str(0, ..)` stays order-preserving even if
247	            // `slot.args` were non-empty. It exists so that a future
248	            // relaxation of drain-once surfaces here for a deliberate
249	            // re-decision, instead of silently changing this from an
250	            // assignment to a splice unnoticed.
251	            debug_assert!(
252	                slot.args.is_empty(),
253	                "a resolved slot drains its args on every delta"
254	            );
255	            slot.args.insert_str(0, &old.args);
256	
257	            // The canonical slot has already emitted its name, so the migrating
258	            // fragment can never reach a consumer: the flush condition below
259	            // tests `name_emitted` and will not fire again for this call. It
260	            // must not be left sitting in `pending` either — `flush_buffered_names`
261	            // skips entries whose call_id already emitted, and
262	            // `warn_unresolved_pending` ignores entries whose key resolves,
263	            // which this one now does. Dropping it silently would recreate the
264	            // undiagnosed loss SMA-550 exists to eliminate, so drop it loudly
265	            // and record it the same way a late wire fragment is recorded.
266	            if !old.name.is_empty() {
267	                if let Some(emitted) = self.name_emitted.get(&canonical) {
268	                    if self.warned_late_name.insert(canonical.clone()) {
269	                        tracing::warn!(
270	                            target: "paigasus::litellm::stream",
271	                            %call_id,
272	                            fragment = %old.name,
273	                            emitted = %emitted,
274	                            "tool-call name fragment buffered under another correlation \
275	                             key arrived after the name was emitted; it cannot be \
276	                             recovered and is dropped"
277	                        );
278	                    }
279	                    return canonical;
280	                }
281	            }
282	
283	            // A migrating fragment identical to what the canonical slot already
284	            // holds is a whole-name repeat, not a continuation — the same case
285	            // the wire path guards below, for the same reason: a backend that
286	            // resends the complete name on every delta would otherwise get
287	            // "search" + "search" -> "searchsearch". Pre-SMA-550 this shape
288	            // emitted "search" correctly, so concatenating unconditionally here
289	            // is a regression, not merely an unhandled edge.
290	            if !old.name.is_empty() && old.name != slot.name {
291	                if !slot.name.is_empty() {
292	                    tracing::warn!(
293	                        target: "paigasus::litellm::stream",
294	                        %call_id,
295	                        "tool-call name fragments for one call arrived under two \
296	                         correlation keys; merging in buffer-creation order, which \
297	                         may misorder them if the two keys interleaved"
298	                    );
299	                }
300	                // Order by creation `seq`, not by which buffer is migrating.
301	                // Both orderings are reachable, and a plain prepend or a plain
302	                // append is wrong in exactly one of them (SMA-550 §Merge order).
303	                if old.seq < slot.seq {
304	                    slot.name.insert_str(0, &old.name);
305	                } else {
306	                    slot.name.push_str(&old.name);
307	                }
308	            }
309	            // Claimed whenever the migrating buffer is the older one, even if
310	            // its name was a repeat or empty: `seq` carries the call's wire
311	            // position for the end-of-stream flush order, independently of
312	            // whether any name text moved.
313	            if old.seq < slot.seq {
314	                slot.seq = old.seq;
315	            }
316	        }
317	
318	        // `flush_buffered_names` and `warn_unresolved_pending` both resolve a
319	        // pending key through `tool_calls`. Without this the canonical key
320	        // resolves to nothing: the call is skipped at flush AND then falsely
321	        // reported as an unresolved loss. Pinned by
322	        // `canonical_key_resolves_through_tool_calls`.
323	        self.tool_calls
324	            .entry(canonical.clone())
325	            .or_insert_with(|| call_id.to_owned());
326	        canonical
327	    }
