329	    /// Consume one chunk. Never emits `Finish`.
330	    pub(crate) fn consume(&mut self, chunk: StreamChunk) -> Vec<ModelEvent> {
331	        let mut out = Vec::new();
332	
333	        if chunk.choices.len() > 1 && !self.warned_multi_choice {
334	            self.warned_multi_choice = true;
335	            tracing::warn!(
336	                target: "paigasus::litellm::stream",
337	                n = chunk.choices.len(),
338	                "response carries multiple choices; only the first is read"
339	            );
340	        }
341	
342	        if let Some(choice) = chunk.choices.first() {
343	            if let Some(delta) = &choice.delta {
344	                if let Some(text) = delta.content.as_deref().filter(|s| !s.is_empty()) {
345	                    out.push(ModelEvent::TokenDelta {
346	                        text: text.to_owned(),
347	                    });
348	                }
349	                let reasoning = delta
350	                    .reasoning_content
351	                    .as_deref()
352	                    .or(delta.reasoning.as_deref())
353	                    .filter(|s| !s.is_empty());
354	                if let Some(text) = reasoning {
355	                    out.push(ModelEvent::ReasoningDelta {
356	                        text: text.to_owned(),
357	                    });
358	                }
359	                if let Some(tcs) = &delta.tool_calls {
360	                    // A positional key is only safe to synthesize when no
361	                    // entry in *this* array carries an explicit `index` —
362	                    // otherwise a synthesized `Key::Index(pos)` can collide
363	                    // with a genuine explicit index elsewhere in the same
364	                    // array. See the module docs.
365	                    let any_explicit_index = tcs.iter().any(|tc| tc.index.is_some());
366	                    for (pos, tc) in tcs.iter().enumerate() {
367	                        self.handle_tool_call(tc, pos, any_explicit_index, &mut out);
368	                    }
369	                }
370	            }
371	            if let Some(reason) = &choice.finish_reason {
372	                // Buffered — see the module docs.
373	                self.finish_reason = Some(reason.clone());
374	            }
375	        }
376	
377	        if let Some(u) = &chunk.usage {
378	            out.push(ModelEvent::Usage {
379	                input_tokens: u.prompt_tokens,
380	                output_tokens: u.completion_tokens,
381	                cached_input_tokens: u
382	                    .prompt_tokens_details
383	                    .as_ref()
384	                    .and_then(|d| d.cached_tokens),
385	                reasoning_tokens: u
386	                    .completion_tokens_details
387	                    .as_ref()
388	                    .and_then(|d| d.reasoning_tokens),
389	            });
390	        }
391	
392	        out
393	    }
