395	    fn handle_tool_call(
396	        &mut self,
397	        tc: &ToolCallChunk,
398	        pos: usize,
399	        any_explicit_index: bool,
400	        out: &mut Vec<ModelEvent>,
401	    ) {
402	        // A blank `id` is not an identity, so it must not become `Key::Id("")`
403	        // — two such entries would share one slot and merge into a single
404	        // call. Filtering it out here sends the delta to the same arms that
405	        // handle an absent id: positional keying, or the loud skip when
406	        // another entry in this array carries an explicit index. Registration
407	        // into `tool_calls` below still reads `tc.id` directly, so a blank id
408	        // that reaches it is still recorded and still resolves to `""`. An
409	        // entry taking the ambiguity skip returns before that point, so it is
410	        // neither registered nor canonicalized (SMA-616).
411	        let key = match (tc.index, tc.id.as_deref().filter(|id| !id.is_empty())) {
412	            (Some(i), _) => Key::Index(i),
413	            (None, Some(id)) => Key::Id(id.to_owned()),
414	            (None, None) if any_explicit_index => {
415	                // A synthesized positional key would risk colliding with a
416	                // genuine explicit `index` elsewhere in this same array
417	                // (e.g. entry 0 explicitly `index: 1`, entry 1 has neither
418	                // — pos 1 would collide with `Key::Index(1)`). That mixes
419	                // two distinct calls into one and corrupts both, which is
420	                // worse than dropping this entry, so skip it loudly.
421	                tracing::warn!(
422	                    target: "paigasus::litellm::stream",
423	                    pos,
424	                    "tool-call delta at this position has neither index nor id, and \
425	                     another entry in the same array carries an explicit index; \
426	                     skipping to avoid a key collision"
427	                );
428	                return;
429	            }
430	            (None, None) => {
431	                tracing::debug!(
432	                    target: "paigasus::litellm::stream",
433	                    pos,
434	                    "tool-call delta has neither index nor id; correlating by position"
435	                );
436	                Key::Index(pos as u32)
437	            }
438	        };
439	
440	        // Both signals test the effective fragment, so a backend sending
441	        // `"name": ""` behaves like one omitting the field.
442	        let name_frag = tc
443	            .function
444	            .as_ref()
445	            .and_then(|f| f.name.as_deref())
446	            .unwrap_or("");
447	        let args_frag = tc
448	            .function
449	            .as_ref()
450	            .and_then(|f| f.arguments.as_deref())
451	            .unwrap_or("");
452	
453	        // Captured before the match so the guard below reads a plain `bool`
454	        // rather than borrowing `self` while `tool_calls` is borrowed mutably.
455	        let blank_already_emitted = self.blank_emitted.contains(&key);
456	
457	        if let Some(id) = tc.id.as_deref() {
458	            match self.tool_calls.get_mut(&key) {
459	                // First id wins, so a backend that changes a call's id
460	                // mid-stream cannot re-point an in-flight call. The one
461	                // exception is an id already recorded as empty: `canonicalize`
462	                // treats a blank id as "no identity yet" rather than as an
463	                // identity, so a real id arriving later must be allowed to
464	                // replace it — otherwise the blank sticks and the call reaches
465	                // the consumer under an empty `call_id` even though the backend
466	                // eventually supplied a real one.
467	                //
468	                // The upgrade is withheld once this key has already emitted a
469	                // delta under the blank id. Replacing then would split one call
470	                // across two `call_id`s: the name would have gone out under
471	                // `""` and every later delta under the real id, leaving the
472	                // real id with zero name-carrying deltas. That is an "exactly
473	                // once" violation on a *non-blank* `call_id` — worse than the
474	                // stuck blank, and one the pre-SMA-619 translator did not have.
475	                // Keeping the blank keeps the call whole (SMA-619).
476	                Some(existing)
477	                    if existing.is_empty() && !id.is_empty() && !blank_already_emitted =>
478	                {
479	                    *existing = id.to_owned();
480	                }
481	                // Reached only when `blank_already_emitted` blocked the arm
482	                // above. Warned rather than absorbed into the no-op arm below:
483	                // this discards a real `call_id` the backend supplied, and the
484	                // decision to keep the blank is only defensible if it is
485	                // visible. `canonicalize`'s blank-id warning does not cover it
486	                // — that one fires on the first delta, before this id was ever
487	                // seen, and never names it.
488	                Some(existing) if existing.is_empty() && !id.is_empty() => {
489	                    if self.warned_withheld_upgrade.insert(key.clone()) {
490	                        tracing::warn!(
491	                            target: "paigasus::litellm::stream",
492	                            ?key,
493	                            discarded_id = %id,
494	                            "a real tool-call id arrived after this key already emitted \
495	                             under a blank id; withholding the upgrade so the call is \
496	                             not split across two call_ids. The call reaches the \
497	                             consumer under an empty call_id"
498	                        );
499	                    }
500	                }
501	                Some(_) => {}
502	                None => {
503	                    self.tool_calls.insert(key.clone(), id.to_owned());
504	                }
505	            }
506	        }
507	
508	        let Some(call_id) = self.tool_calls.get(&key).cloned() else {
509	            // No id yet — buffer both fragments.
510	            self.ensure_pending(&key);
511	            let slot = self
512	                .pending
513	                .get_mut(&key)
514	                .expect("ensure_pending just inserted this key");
515	            slot.name.push_str(name_frag);
516	            slot.args.push_str(args_frag);
517	            return;
518	        };
519	
520	        // From here on, one call_id owns exactly one state entry.
521	        let key = self.canonicalize(key, &call_id);
522	
523	        // A name fragment arriving after the name was emitted cannot be
524	        // recovered — the event is already downstream. Warn once per call,
525	        // and not at all when the fragment merely repeats what was emitted.
526	        if let Some(emitted) = self.name_emitted.get(&key) {
527	            if !name_frag.is_empty()
528	                && !emitted.starts_with(name_frag)
529	                && self.warned_late_name.insert(key.clone())
530	            {
531	                tracing::warn!(
532	                    target: "paigasus::litellm::stream",
533	                    %call_id,
534	                    fragment = %name_frag,
535	                    emitted = %emitted,
536	                    "tool-call name fragment arrived after the name was emitted; \
537	                     it cannot be recovered and is dropped"
538	                );
539	            }
540	        }
541	
542	        // Once a name has flushed, nothing reads `slot.name` again for the
543	        // life of the stream — skip the accumulation so a backend that
544	        // repeats the whole name on every delta doesn't grow an unread
545	        // `String` for no reason (SMA-547 §4). Captured from the same
546	        // `name_emitted` state the flush condition below re-derives, so it
547	        // cannot change which deltas flush.
548	        let already_emitted = self.name_emitted.contains_key(&key);
549	
550	        self.ensure_pending(&key);
551	        let slot = self
552	            .pending
553	            .get_mut(&key)
554	            .expect("ensure_pending just inserted this key");
555	        // A name fragment identical to the name accumulated so far is treated
556	        // as a whole-name repeat and skipped, not appended -- otherwise a
557	        // backend that resends the complete function name on every delta
558	        // (instead of incrementally fragmenting it) would double it, e.g.
559	        // "search" + "search" -> "searchsearch". Pre-fix this case emitted
560	        // "search" correctly, so appending unconditionally here would be a
561	        // regression, not merely an unhandled edge.
562	        //
563	        // Known, accepted limitation: a tool genuinely named e.g. "aa" whose
564	        // name fragments as "a" + "a" cannot be told apart from a repeat
565	        // under this rule and assembles as "a", not "aa". This matches
566	        // pre-SMA-547 behaviour (the old code emitted "a" on the first delta
567	        // and suppressed the second as a duplicate), so it is not a new
568	        // regression -- whereas omitting this guard regresses the
569	        // repeated-whole-name case from correct to corrupted. Do not remove
570	        // this guard without re-deciding that trade-off.
571	        if !already_emitted && slot.name != name_frag {
572	            slot.name.push_str(name_frag);
573	        }
574	        // `args` is drain-once.
575	        let mut args = std::mem::take(&mut slot.args);
576	        args.push_str(args_frag);
577	
578	        // The name is complete when either signal appears: this delta carried
579	        // arguments, or this delta carried no name fragment.
580	        let flush = !self.name_emitted.contains_key(&key)
581	            && !slot.name.is_empty()
582	            && (!args_frag.is_empty() || name_frag.is_empty());
583	
584	        let emit_name = if flush {
585	            let name = std::mem::take(&mut slot.name);
586	            self.name_emitted.insert(key.clone(), name.clone());
587	            Some(name)
588	        } else {
589	            None
590	        };
591	
592	        if slot.name.is_empty() && slot.args.is_empty() {
593	            self.pending.remove(&key);
594	        }
595	
596	        if emit_name.is_none() && args.is_empty() {
597	            return;
598	        }
599	
600	        // Record that this key has emitted under a blank id, so the
601	        // replacement rule above cannot later split the call in two.
602	        //
603	        // Placement after the early return is load-bearing: a delta that
604	        // emits nothing has published the blank id to nobody, so it must not
605	        // close the upgrade window. Pinned by
606	        // `a_real_id_replaces_a_blank_one_on_the_same_wire_key`, whose first
607	        // delta emits nothing and whose upgrade must still be allowed.
608	        if call_id.is_empty() {
609	            debug_assert!(
610	                matches!(key, Key::Index(_)),
611	                "a blank call_id is only reachable under an Index key"
612	            );
613	            self.blank_emitted.insert(key);
614	        }
615	
616	        out.push(ModelEvent::ToolCallDelta {
617	            call_id,
618	            name: emit_name,
619	            args_delta: args,
620	        });
621	    }
