623	    /// Emit any tool name still buffered at end-of-stream.
624	    ///
625	    /// Reached by the zero-argument shape, where no `arguments` fragment ever
626	    /// arrives to signal the name is complete. Correctness, not diagnostics:
627	    /// the agent loop dispatches on the presence of an `Item::ToolCall` and
628	    /// reads the tool to run from its `name`.
629	    ///
630	    /// Skips entries whose `id` never resolved (nothing to emit under) and
631	    /// entries whose resolved `call_id` already emitted a name. Since SMA-550
632	    /// the latter check is redundant — canonicalization gives each `call_id`
633	    /// one key — and is kept as a net; see the comment at its `continue`.
634	    ///
635	    /// The at-most-one invariant the net enforces is scoped to **non-blank**
636	    /// `call_id`s. A blank id cannot identify a call, so it is never claimed;
637	    /// two parallel blank-id calls each flush their own name under `""`
638	    /// (SMA-616).
639	    fn flush_buffered_names(&mut self) -> Vec<ModelEvent> {
640	        // Sorted by buffer-creation order, not by `Key`. After SMA-550 every
641	        // resolved key is `Key::Id(call_id)`, so sorting by `Key` would mean
642	        // lexicographic-by-call_id — silently reordering parallel calls
643	        // against the wire. `seq` is unique per buffer, so this is a total,
644	        // deterministic order that matches first appearance.
645	        let mut keys: Vec<Key> = self.pending.keys().cloned().collect();
646	        keys.sort_by_key(|k| self.pending[k].seq);
647	
648	        // Seeded from keys that already emitted, so a call flushed mid-stream
649	        // cannot be re-emitted here. The `.filter(|c| !c.is_empty())` is
650	        // redundant on its own: the loop guard further down
651	        // (`!call_id.is_empty() && !already.insert(...)`) already
652	        // short-circuits before `insert` ever runs for a blank id, so a blank
653	        // entry in `already` could never change what gets claimed. Kept anyway
654	        // so this seed states the same "blank ids are exempt" rule as the
655	        // guard below, in the same place — and so it matches
656	        // `providers-openai`'s seed, which states it identically (SMA-616).
657	        let mut already: HashSet<String> = self
658	            .name_emitted
