455	        let blank_already_emitted = self.blank_emitted.contains(&key);
456	
457	        if let Some(id) = tc.id.as_deref() {
458	            match self.tool_calls.get_mut(&key) {
459	                // First id wins, so a backend that changes a call's id
460	                // mid-stream cannot re-point an in-flight call. The one
461	                // exception is an id already recorded as empty: `canonicalize`
