491	                            target: "paigasus::litellm::stream",
492	                            ?key,
493	                            discarded_id = %id,
494	                            "a real tool-call id arrived after this key already emitted \
495	                             under a blank id; withholding the upgrade so the call is \
496	                             not split across two call_ids. The call reaches the \
497	                             consumer under an empty call_id"
