105	    pub fn consume(&mut self, ev: ConverseStreamOutput) -> Vec<Result<ModelEvent, ModelError>> {
106	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
107	
108	        match ev {
109	            // ── events that produce no output ─────────────────────────────────
110	            ConverseStreamOutput::MessageStart(_) => {}
111	            ConverseStreamOutput::ContentBlockStop(_) => {}
112	
113	            // ── content block start ───────────────────────────────────────────
114	            ConverseStreamOutput::ContentBlockStart(e) => {
115	                let idx = e.content_block_index();
116	                match e.start() {
117	                    Some(ContentBlockStart::ToolUse(tu)) => {
118	                        let call_id = tu.tool_use_id().to_owned();
119	                        let name = tu.name().to_owned();
120	
121	                        if self.synthesizing && name == SYNTHESIZED_TOOL_NAME {
122	                            self.synthesized_block_index = Some(idx);
123	                        } else {
124	                            self.real_tool_fired = true;
125	                            // Emit the name-carrying delta immediately on block
126	                            // start (mirrors the Anthropic provider's behaviour
127	                            // of emitting name on the first input-json delta).
128	                            // We *don't* emit here — we wait for the first
129	                            // tool-input delta so the call_id→state map is
130	                            // consistent.
131	                        }
132	                        self.blocks.insert(
133	                            idx,
134	                            BlockState::ToolUse {
135	                                call_id,
136	                                name,
137	                                name_emitted: false,
138	                            },
139	                        );
140	                    }
141	                    Some(ContentBlockStart::Image(_) | ContentBlockStart::ToolResult(_)) => {
142	                        // Not a tool we translate; record nothing.
143	                    }
144	                    Some(_) | None => {
145	                        // Text or unknown start: record as text block.
146	                        self.blocks.insert(idx, BlockState::Text);
147	                    }
148	                }
149	            }
150	
151	            // ── content block delta ───────────────────────────────────────────
152	            ConverseStreamOutput::ContentBlockDelta(e) => {
153	                let idx = e.content_block_index();
154	                match e.delta() {
155	                    Some(ContentBlockDelta::Text(text)) => {
156	                        out.push(Ok(ModelEvent::TokenDelta { text: text.clone() }));
157	                    }
158	                    Some(ContentBlockDelta::ToolUse(tu_delta)) => {
159	                        let input = tu_delta.input().to_owned();
160	                        let is_synth = Some(idx) == self.synthesized_block_index;
161	
162	                        if is_synth {
163	                            // Remap synthesized tool input to TokenDelta.
164	                            out.push(Ok(ModelEvent::TokenDelta { text: input }));
165	                        } else if let Some(BlockState::ToolUse {
166	                            call_id,
167	                            name,
168	                            name_emitted,
169	                        }) = self.blocks.get_mut(&idx)
170	                        {
171	                            let emit_name = if *name_emitted {
172	                                None
173	                            } else {
174	                                *name_emitted = true;
175	                                Some(name.clone())
176	                            };
177	                            out.push(Ok(ModelEvent::ToolCallDelta {
178	                                call_id: call_id.clone(),
179	                                name: emit_name,
180	                                args_delta: input,
181	                            }));
182	                        }
183	                        // If no block state (shouldn't happen for well-formed
184	                        // streams), silently drop rather than panic.
185	                    }
186	                    Some(ContentBlockDelta::ReasoningContent(rc)) => match rc {
187	                        ReasoningContentBlockDelta::Text(text) => {
